-- 0138: the Qurʾānic plurals of the Ghāfir 40:2–3 lemmas, into the lemma layer (0137). Each checked in the
-- muṣḥaf (qr_word_occurrence: the plural is filed under the same lemma) and against the lexicons + Lane.
-- Not carried over from QR: «تَائِبُونَ» as a plural of تَوْب — it is the plural of تَائِب (QAC files it as
-- its own lemma, AL:b7ec5f0be53265e6b2a99b726f); no book gives تَوْب a plural (al-Akhfash, in al-Ṣiḥāḥ
-- blk_sih_cfd6360980d576c6, reads تَوْب itself as the collective of تَوْبَة).
-- Lexicon fact rows found wrong while checking (recorded, not touched): lf_6c8b5a4770c8308b, lf_e66a8f2d15ea6099,
-- lf_96014d8fa163392d, lf_e09ac8edc8d1acc3, lf_053ebed558478f58, lf_57f919831beaa3b2.
INSERT OR IGNORE INTO ar_ling_sarf_wazn (id, wazn_key, wazn_ar, tier, applies_to, name_en, wazn_order, note_md, status) VALUES ('WZ:fuul_pl', 'fuul_pl', 'فُعُل', 'jam_taksir', 'jam', 'fuʿul (plural)', 300, 'Broken plural pattern.', 'live');
