INSERT OR IGNORE INTO ar_ling_sarf_wazn (id, wazn_key, wazn_ar, tier, applies_to, name_en, wazn_order, note_md, status) VALUES ('WZ:fualaa_pl', 'fualaa_pl', 'فُعَلَاء', 'jam_taksir', 'jam', 'fuʿalāʾ (plural)', 300, 'Broken plural pattern.', 'live');
INSERT OR IGNORE INTO ar_ling_sarf_wazn (id, wazn_key, wazn_ar, tier, applies_to, name_en, wazn_order, note_md, status) VALUES ('WZ:fuul_long_pl', 'fuul_long_pl', 'فُعُول', 'jam_taksir', 'jam', 'fuʿūl (plural)', 300, 'Broken plural pattern.', 'live');
INSERT OR IGNORE INTO ar_ling_sarf_wazn (id, wazn_key, wazn_ar, tier, applies_to, name_en, wazn_order, note_md, status) VALUES ('WZ:afilaa_pl', 'afilaa_pl', 'أَفْعِلَاء', 'jam_taksir', 'jam', 'afʿilāʾ (plural)', 300, 'Broken plural pattern.', 'live');
