INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:26ec9894256ccd2fcb77820470:كتب', '26ec9894256ccd2fcb77820470', 'كُتُبٌ', 'كتب', 'GT:noun_process:jam_taksir', 'WZ:fuul_pl', 1, 98, 3, 2, 'فيها كتب قيمة', '["lf_15c8827a96ede9bd", "lf_4c0f5a6298c95abd", "lf_1afddd5163634213"]', 'blk_lane_a17b258ea1f500ca p.2590', 'Pl. كُتُبٌ and كُتْبٌ. (Ṣ.)', 'Also 2:285, 4:136, 21:104, 34:44, 66:12. No plural of few (Sībawayh, in al-Muḥkam): ثلاثة كتب.', 1);
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:3d42f257c274c5d8463f1b8371:اعزه', '3d42f257c274c5d8463f1b8371', 'أَعِزَّةٌ', 'اعزه', 'GT:noun_process:jam_taksir', 'WZ:afila_pl', 1, 5, 54, 18, 'اعزة علي الكافرين', NULL, 'blk_lane_dee9d83df50368cf p.2032', 'the pl. of عَزِيزٌ is عِزَازٌ … and أَعِزَّةٌ … and أَعِزَّآءُ', 'Also 27:34. The books also give عِزَاز and أَعِزَّاء (Ṣiḥāḥ blk_sih_249b69cb8b3620ad; Lisān blk_lsn_7faccc5ba1b9c2fe, citing 5:54; Miṣbāḥ blk_msb_1ebb65d597866856 «وجمعه أعزة»).', 1);
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:9ba7ce572be40ce777e0d44853:علماء', '9ba7ce572be40ce777e0d44853', 'عُلَمَاءُ', 'علماء', 'GT:noun_process:jam_taksir', 'WZ:fualaa_pl', 1, 35, 28, 13, 'انما يخشي الله من عباده العلماء', '["lf_4cd9b41e8dd4da15"]', 'blk_lane_6fc19296c3f54b51 p.2141', 'the former being [properly] pl. of عَلِيمٌ; and عَالِمُونَ is [a] pl. of عَالِمٌ', 'Also 26:197. Properly the plural of عَلِيم (فَعِيل → فُعَلَاء); عَالِم shares it only by carrying its sense (Sībawayh, Ibn Jinnī in Lisān blk_lsn_f086f736f994fec6). In the Qurʾān عَالِم takes عَالِمُونَ.', 1);
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:ea923679f32861b46d50eade95:غافرون', 'ea923679f32861b46d50eade95', 'غَافِرُونَ', 'غافرون', 'GT:noun_process:jam_mudhakkar_salim', NULL, 1, 7, 155, 41, 'وانت خير الغافرين', NULL, NULL, NULL, 'The regular sound plural of a فاعِل adjective; no book needs to state it (Lane p.2274 defines غَافِر, no plural).', 1);
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:2e7a23ca384799c20b92778cf7:ذنوب', '2e7a23ca384799c20b92778cf7', 'ذُنُوبٌ', 'ذنوب', 'GT:noun_process:jam_taksir', 'WZ:fuul_long_pl', 1, 39, 53, 15, 'يغفر الذنوب جميعا', '["lf_9f9529dff82cdc1c", "lf_22c4061d56594a89", "lf_c2dba6fdb3738844"]', 'blk_lane_38a70932e87987f8 p.980', 'pl. ذُنُوبٌ (M, Msb, K) and pl. pl. ذُنُوبَاتٌ', '26 plural uses in the Qurʾān. Not أَذْنَاب — that is the plural of ذَنَب, a tail. Also al-ʿAyn blk_kay_027e544a5013b5bf «والجمع الذنوب».', 1);
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:d598d16f55259b05ab7239513e:اشداء', 'd598d16f55259b05ab7239513e', 'أَشِدَّاءُ', 'اشداء', 'GT:noun_process:jam_taksir', 'WZ:afilaa_pl', 1, 48, 29, 6, 'اشداء علي الكفار', NULL, 'blk_lane_9fbfd2d8b2782dc6 p.1519', 'pl., applied to men, أَشِدَّآءُ', 'Said of men. Lisān blk_lsn_33efc7e3ad2b07b2 «والجمع أشداء وشداد وشدد»; Tāj blk_taj_0974f040fc0d91e5.', 1);
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:d598d16f55259b05ab7239513e:شداد', 'd598d16f55259b05ab7239513e', 'شِدَادٌ', 'شداد', 'GT:noun_process:jam_taksir', 'WZ:fial_pl', 1, 78, 12, 4, 'سبعا شدادا', '["lf_7711ab553dafa3bd", "lf_e691083e4416f025"]', 'blk_lane_9fbfd2d8b2782dc6 p.1519', '[applied to things and men] شِدَادٌ', 'Said of things — heavens, years (12:48) — and of angels (66:6).', 2);
INSERT OR IGNORE INTO ar_ling_root_lemma_jam (id, lemma_id, plural_ar, plural_bare, kind_ref, wazn_id, in_quran, surah, ayah, word_index, needle, lexicon_fact_ids_json, lane_ref, lane_quote_en, note_en, sort_order) VALUES ('JAM:c88f937fab2a9108ab54922b75:الهه', 'c88f937fab2a9108ab54922b75', 'آلِهَةٌ', 'الهه', 'GT:noun_process:jam_taksir', 'WZ:afila_pl', 1, 38, 5, 2, 'اجعل الالهة الها واحدا', '["lf_bcb38f38389ae6af", "lf_f95354a773f45ec9"]', 'blk_lane_b8821100e19ef6c5 p.82', 'pl. آلِهَةٌ: (Mṣb, TA:) which signifies idols', '34 plural uses (أَأْلِهَة → آلِهَة). al-Rāghib (blk_mfr_6ead9cd4d2954e06): God is not to be pluralised; the Arabs did by their belief.', 1);
